import { get } from "./http";

// FETCHUSER and fetchuser were the v1 names.
export function fetchUser(id: string) {
  return get(`/users/${id}`);
}

export function fetchTeam(id: string) {
  return get(`/teams/${id}`);
}

export function fetchOrg(id: string) {
  return get(`/orgs/${id}`);
}

export function FetchUserLegacy(id: string) {
  return get(`/v1/users/${id}`);
}

// Callers: fetchUser for one id, fetchUser in a loop for many.
export const userCache = new Map<string, unknown>();

export const ttl = 60;
export const version = 2;
